command:
const showGenericCard = game.pirateborg.api.showGenericCard;
const grantItem = game.pirateborg.api.grants.grantItem;
const localizeWithFallback = (key, data, fallback) => {
  const text = game.i18n.format(key, data);
  return text === key ? fallback : text;
};

const BAYONET_NAMES = new Set(["bayonet", "bayonets"]);
const normalize = (name) => String(name ?? "").trim().toLowerCase();
const isBayonet = (entry) => entry?.type === "weapon" && BAYONET_NAMES.has(normalize(entry.name));
const isGunpowderReloadable = (entry) =>
  entry?.type === "weapon" &&
  entry?.system?.equipped &&
  entry?.system?.isGunpowderWeapon &&
  entry?.system?.needsReloading &&
  Number(entry?.system?.loadingCount ?? 0) > 0;

// Ensure the character actually has a bayonet ready. Grant one from the compendium
// (already equipped) via the shared grants API if they don't, otherwise just equip
// the one they have.
let bayonet = actor.items.find((i) => isBayonet(i));
if (!bayonet) {
  bayonet = await grantItem(actor, "pirateborg.equipment-melee-weapons;Bayonet", { equip: true });
} else if (!bayonet.system.equipped) {
  await bayonet.update({ "system.equipped": true });
}

const reloadable = actor.items.find((i) => isGunpowderReloadable(i));
const outcomes = [];
if (bayonet && reloadable) {
  const outcomeId = foundry.utils.randomID();
  outcomes.push({
    id: outcomeId,
    type: "attack",
    title: localizeWithFallback("PB.FixBayonetsReloadPrompt", { item: reloadable.name }, `${reloadable.name} still needs reloading.`),
    actionItemId: bayonet.id,
    actionItemName: bayonet.name,
    initiatorActor: actor.id,
    initiatorToken: actor.getActiveTokens()?.[0]?.id,
    button: {
      title: localizeWithFallback("PB.FixBayonetsAttackButton", { item: bayonet.name }, `Attack with ${bayonet.name}`),
      data: {
        type: "button-attack-item",
        id: foundry.utils.randomID(),
        outcome: outcomeId,
      },
    },
  });
}

await showGenericCard({
  actor,
  title: item.name,
  description: bayonet
    ? `Your bayonet (${bayonet.system.damageDie}) is fixed and equipped. You can attack with it on the same turn you reload a black-powder weapon.`
    : `You can attack with your bayonet on the same turn you reload a black-powder weapon.`,
  outcomes,
});
